/* net_codec.h: byte-exact big-endian codec shared by net_file_delivery.c and net_kq_delivery.c.
 * The fixtures below are hand-written byte literals (big-endian, written out from the field
 * values); they match what the old hand-shifted put_u16/32/64 (net_file_delivery.c) and the
 * old kq_w_t writer (net_kq_delivery.c) produced, as checked by comparing outputs before the
 * change. They are not generated by this codec and must never change. */
#include "net_codec.h"

#include <stdio.h>
#include <string.h>

#define ASSERT(c) do { if (!(c)) { fprintf(stderr, "FAIL line %d: %s\n", __LINE__, #c); return 1; } } while (0)

static const uint8_t FIX_FD_SEQ[] = {
    0xA1, 0xB2, 0x00, 0x00, 0xDE, 0xAD, 0xBE, 0xEF, 0x11, 0x22, 0x33, 0x44,
    0x55, 0x66, 0x77, 0x88, 0x00, 0x00, 0x00, 0x01,
};
static const uint8_t FIX_KQ_SEQ[] = {
    0xAA, 0xBB, 0x01, 0x02, 0x03, 0x04, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06,
    0x07, 0x08, 0x02, 0x61, 0x62, 0x00, 0xFF, 0xFF, 0xFF, 0xFE,
};
static const uint8_t FIX_U64_HI[] = {0x80, 0, 0, 0, 0, 0, 0, 0x01};

static int test_file_delivery_sequence(void)
{
    uint8_t buf[64];
    fl_bytes_writer_t w;
    uint16_t off = 0, a = 0, b = 1;
    uint32_t c = 0, e = 0;
    uint64_t d = 0;

    fl_bytes_writer_init(&w, buf, sizeof buf);
    ASSERT(fl_codec_put_u16(&w, 0xA1B2) == FL_RESULT_OK);
    ASSERT(fl_codec_put_u16(&w, 0x0000) == FL_RESULT_OK);
    ASSERT(fl_codec_put_u32(&w, 0xDEADBEEFu) == FL_RESULT_OK);
    ASSERT(fl_codec_put_u64(&w, 0x1122334455667788ULL) == FL_RESULT_OK);
    ASSERT(fl_codec_put_u32(&w, 1u) == FL_RESULT_OK);
    ASSERT(w.len == sizeof FIX_FD_SEQ && memcmp(buf, FIX_FD_SEQ, w.len) == 0);

    ASSERT(fl_codec_get_u16(buf, w.len, &off, &a) == FL_RESULT_OK && a == 0xA1B2);
    ASSERT(fl_codec_get_u16(buf, w.len, &off, &b) == FL_RESULT_OK && b == 0);
    ASSERT(fl_codec_get_u32(buf, w.len, &off, &c) == FL_RESULT_OK && c == 0xDEADBEEFu);
    ASSERT(fl_codec_get_u64(buf, w.len, &off, &d) == FL_RESULT_OK && d == 0x1122334455667788ULL);
    ASSERT(fl_codec_get_u32(buf, w.len, &off, &e) == FL_RESULT_OK && e == 1u);
    ASSERT(off == w.len);
    return 0;
}

static int test_overflow_and_short_read(void)
{
    uint8_t buf[5];
    fl_bytes_writer_t w;
    uint16_t off = 0;
    uint32_t v32 = 7;
    uint64_t v64 = 7;
    uint16_t v16 = 7;

    fl_bytes_writer_init(&w, buf, sizeof buf);
    ASSERT(fl_codec_put_u32(&w, 1u) == FL_RESULT_OK);
    /* No partial write: len stays, the byte after it is untouched. */
    ASSERT(fl_codec_put_u16(&w, 0xFFFF) == FL_RESULT_NOMEM && w.len == 4u);
    ASSERT(fl_codec_put_u64(&w, 1u) == FL_RESULT_NOMEM && w.len == 4u);
    ASSERT(fl_codec_put_u8(&w, 9u) == FL_RESULT_OK && w.len == 5u);
    ASSERT(fl_codec_put_u8(&w, 9u) == FL_RESULT_NOMEM);
    ASSERT(fl_codec_put_u16(NULL, 1u) == FL_RESULT_NOMEM);

    off = 4u;
    ASSERT(fl_codec_get_u16(buf, 5u, &off, &v16) == FL_RESULT_INVAL && off == 4u && v16 == 7u);
    off = 2u;
    ASSERT(fl_codec_get_u32(buf, 5u, &off, &v32) == FL_RESULT_INVAL && off == 2u && v32 == 7u);
    off = 0u;
    ASSERT(fl_codec_get_u64(buf, 5u, &off, &v64) == FL_RESULT_INVAL && off == 0u && v64 == 7u);
    ASSERT(fl_codec_get_u16(NULL, 5u, &off, &v16) == FL_RESULT_INVAL);
    ASSERT(fl_codec_get_u16(buf, 5u, NULL, &v16) == FL_RESULT_INVAL);
    ASSERT(fl_codec_get_u16(buf, 5u, &off, NULL) == FL_RESULT_INVAL);
    /* An offset past the cap must not wrap into a pass. */
    off = 0xFFFFu;
    ASSERT(fl_codec_get_u16(buf, 5u, &off, &v16) == FL_RESULT_INVAL);
    return 0;
}

static int test_kq_sequence(void)
{
    uint8_t buf[512];
    fl_bytes_writer_t w;
    fl_bytes_reader_t r;
    uint8_t two[2];
    uint32_t a = 0, z = 0;
    uint64_t b = 0;
    char s1[8], s2[8];

    fl_bytes_writer_init(&w, buf, sizeof buf);
    ASSERT(fl_codec_put_bytes(&w, "\xAA\xBB", 2) == FL_RESULT_OK);
    ASSERT(fl_codec_put_u32(&w, 0x01020304u) == FL_RESULT_OK);
    ASSERT(fl_codec_put_u64(&w, 0x0102030405060708ULL) == FL_RESULT_OK);
    ASSERT(fl_codec_put_str8(&w, "ab") == FL_RESULT_OK);
    ASSERT(fl_codec_put_str8(&w, "") == FL_RESULT_OK);
    ASSERT(fl_codec_put_u32(&w, 0xFFFFFFFEu) == FL_RESULT_OK);
    ASSERT(w.len == sizeof FIX_KQ_SEQ && memcmp(buf, FIX_KQ_SEQ, w.len) == 0);

    fl_bytes_reader_init(&r, buf, w.len);
    ASSERT(fl_bytes_reader_read_bytes(&r, two, 2) == FL_RESULT_OK && two[0] == 0xAA && two[1] == 0xBB);
    ASSERT(fl_bytes_reader_read_u32(&r, &a) == FL_RESULT_OK && a == 0x01020304u);
    ASSERT(fl_bytes_reader_read_u64(&r, &b) == FL_RESULT_OK && b == 0x0102030405060708ULL);
    ASSERT(fl_bytes_reader_read_str8(&r, s1, sizeof s1) == FL_RESULT_OK && strcmp(s1, "ab") == 0);
    ASSERT(fl_bytes_reader_read_str8(&r, s2, sizeof s2) == FL_RESULT_OK && s2[0] == '\0');
    ASSERT(fl_bytes_reader_read_u32(&r, &z) == FL_RESULT_OK && z == 0xFFFFFFFEu);
    ASSERT(fl_bytes_reader_remaining(&r) == 0u && !r.bad);

    fl_bytes_writer_init(&w, buf, sizeof buf);
    ASSERT(fl_codec_put_u64(&w, 0x8000000000000001ULL) == FL_RESULT_OK);
    ASSERT(w.len == sizeof FIX_U64_HI && memcmp(buf, FIX_U64_HI, w.len) == 0);
    return 0;
}

static int test_str8_rules(void)
{
    uint8_t buf[300];
    fl_bytes_writer_t w;
    fl_bytes_reader_t r;
    char out[8];
    char longs[300];

    memset(longs, 'x', 256);
    longs[256] = '\0';
    fl_bytes_writer_init(&w, buf, sizeof buf);
    ASSERT(fl_codec_put_str8(&w, longs) == FL_RESULT_INVAL && w.len == 0u);
    longs[255] = '\0';
    ASSERT(fl_codec_put_str8(&w, longs) == FL_RESULT_OK && w.len == 256u && buf[0] == 255u);
    fl_bytes_writer_init(&w, buf, 4);
    ASSERT(fl_codec_put_str8(&w, "abcd") == FL_RESULT_NOMEM && w.len == 0u);
    ASSERT(fl_codec_put_str8(&w, NULL) == FL_RESULT_OK && w.len == 1u && buf[0] == 0u);

    /* Length >= cap, short buffer and embedded NUL all fail and clear the output. */
    {
        const uint8_t big[] = {8, 'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'};
        const uint8_t shortb[] = {3, 'a'};
        const uint8_t nul[] = {3, 'a', 0, 'b'};
        strcpy(out, "zz");
        fl_bytes_reader_init(&r, big, sizeof big);
        ASSERT(fl_bytes_reader_read_str8(&r, out, sizeof out) == FL_RESULT_INVAL && r.bad && out[0] == '\0');
        strcpy(out, "zz");
        fl_bytes_reader_init(&r, shortb, sizeof shortb);
        ASSERT(fl_bytes_reader_read_str8(&r, out, sizeof out) == FL_RESULT_INVAL && r.bad && out[0] == '\0');
        strcpy(out, "zz");
        fl_bytes_reader_init(&r, nul, sizeof nul);
        ASSERT(fl_bytes_reader_read_str8(&r, out, sizeof out) == FL_RESULT_INVAL && r.bad && out[0] == '\0');
    }
    return 0;
}

static int test_reader_sticky(void)
{
    const uint8_t data[] = {1, 2, 3, 4, 5};
    fl_bytes_reader_t r;
    uint32_t v = 9;
    uint8_t b = 9;

    fl_bytes_reader_init(&r, data, sizeof data);
    ASSERT(fl_bytes_reader_read_u32(&r, &v) == FL_RESULT_OK && v == 0x01020304u);
    ASSERT(fl_bytes_reader_read_u32(&r, &v) == FL_RESULT_INVAL && r.bad && v == 0x01020304u);
    /* Once bad, even a read that would fit fails. */
    ASSERT(fl_bytes_reader_read_u8(&r, &b) == FL_RESULT_INVAL && b == 9u);
    return 0;
}

static int test_put_bytes_guards_and_u16_reader(void)
{
    uint8_t buf[4] = {0};
    fl_bytes_writer_t w;
    const uint8_t data[] = {1, 2, 3, 4, 5, 6};
    fl_bytes_reader_t r;
    fl_bytes_view_t view;
    uint16_t v16 = 9, off = 0;

    fl_bytes_writer_init(&w, buf, sizeof buf);
    /* n > 0 with no source is INVAL (and writes nothing); n == 0 with no source is fine. */
    ASSERT(fl_codec_put_bytes(&w, NULL, 1u) == FL_RESULT_INVAL && w.len == 0u);
    ASSERT(fl_codec_put_bytes(&w, NULL, 0u) == FL_RESULT_OK && w.len == 0u);
    /* A corrupt writer (len past cap) is refused, even for a zero-length put. */
    w.len = (uint16_t)(w.cap + 1u);
    ASSERT(fl_codec_put_bytes(&w, data, 0u) == FL_RESULT_NOMEM);
    ASSERT(fl_codec_put_bytes(&w, data, 1u) == FL_RESULT_NOMEM && w.len == w.cap + 1u);

    /* Views: borrowed, bounded, off moves only on success. */
    off = 1u;
    ASSERT(fl_codec_get_view(data, 6u, &off, 3u, &view) == FL_RESULT_OK && view.data == data + 1 &&
           view.len == 3u && off == 4u);
    ASSERT(fl_codec_get_view(data, 6u, &off, 3u, &view) == FL_RESULT_INVAL && off == 4u);

    /* read_u16: value, sticky bad on a short read, and a NULL destination is a failed read. */
    fl_bytes_reader_init(&r, data, 3u);
    ASSERT(fl_bytes_reader_read_u16(&r, &v16) == FL_RESULT_OK && v16 == 0x0102u && !r.bad);
    ASSERT(fl_bytes_reader_read_u16(&r, &v16) == FL_RESULT_INVAL && r.bad && v16 == 0x0102u);
    fl_bytes_reader_init(&r, data, sizeof data);
    ASSERT(fl_bytes_reader_read_u16(&r, NULL) == FL_RESULT_INVAL && r.bad);
    fl_bytes_reader_init(&r, data, sizeof data);
    ASSERT(fl_bytes_reader_read_u32(&r, NULL) == FL_RESULT_INVAL && r.bad);
    fl_bytes_reader_init(&r, data, sizeof data);
    ASSERT(fl_bytes_reader_read_u64(&r, NULL) == FL_RESULT_INVAL && r.bad);
    fl_bytes_reader_init(&r, data, sizeof data);
    ASSERT(fl_bytes_reader_read_u8(&r, NULL) == FL_RESULT_INVAL && r.bad);
    return 0;
}

static int test_null_dest_and_null_output(void)
{
    fl_bytes_writer_t w;
    fl_bytes_reader_t r;
    const uint8_t data[] = {1, 2, 3, 4, 5, 6, 7, 8};
    uint8_t b = 9;
    uint16_t v16 = 9;
    uint32_t v32 = 9;
    uint64_t v64 = 9;
    char sink[4];

    /* Null destination buffer, n > 0: INVAL and len stays 0. n == 0 still succeeds. */
    fl_bytes_writer_init(&w, NULL, 16);
    ASSERT(fl_codec_put_bytes(&w, data, 1u) == FL_RESULT_INVAL && w.len == 0u);
    ASSERT(fl_codec_put_bytes(&w, data, 0u) == FL_RESULT_OK && w.len == 0u);

    /* put_str8 into a null buffer with room for the length byte: INVAL, len stays 0. */
    fl_bytes_writer_init(&w, NULL, 16);
    ASSERT(fl_codec_put_str8(&w, "ab") == FL_RESULT_INVAL && w.len == 0u);
    fl_bytes_writer_init(&w, NULL, 16);
    ASSERT(fl_codec_put_str8(&w, "") == FL_RESULT_INVAL && w.len == 0u);
    fl_bytes_writer_init(&w, NULL, 16);
    ASSERT(fl_codec_put_str8(&w, NULL) == FL_RESULT_INVAL && w.len == 0u);

    /* Null output sets sticky bad; the next read fails and does not write. */
    fl_bytes_reader_init(&r, data, sizeof data);
    ASSERT(fl_bytes_reader_read_u16(&r, NULL) == FL_RESULT_INVAL && r.bad);
    ASSERT(fl_bytes_reader_read_u8(&r, &b) == FL_RESULT_INVAL && b == 9u);

    fl_bytes_reader_init(&r, data, sizeof data);
    ASSERT(fl_bytes_reader_read_u32(&r, NULL) == FL_RESULT_INVAL && r.bad);
    ASSERT(fl_bytes_reader_read_u8(&r, &b) == FL_RESULT_INVAL && b == 9u);

    fl_bytes_reader_init(&r, data, sizeof data);
    ASSERT(fl_bytes_reader_read_u64(&r, NULL) == FL_RESULT_INVAL && r.bad);
    ASSERT(fl_bytes_reader_read_u8(&r, &b) == FL_RESULT_INVAL && b == 9u);

    fl_bytes_reader_init(&r, data, sizeof data);
    ASSERT(fl_bytes_reader_read_str8(&r, NULL, sizeof sink) == FL_RESULT_INVAL && r.bad);
    ASSERT(fl_bytes_reader_read_u8(&r, &b) == FL_RESULT_INVAL && b == 9u);

    /* A null reader is INVAL and does not crash or touch the output. */
    ASSERT(fl_bytes_reader_read_u16(NULL, &v16) == FL_RESULT_INVAL && v16 == 9u);
    ASSERT(fl_bytes_reader_read_u32(NULL, &v32) == FL_RESULT_INVAL && v32 == 9u);
    ASSERT(fl_bytes_reader_read_u64(NULL, &v64) == FL_RESULT_INVAL && v64 == 9u);
    strcpy(sink, "zz");
    ASSERT(fl_bytes_reader_read_str8(NULL, sink, sizeof sink) == FL_RESULT_INVAL && sink[0] == 'z');
    return 0;
}

/* The sticky writer: same bytes as the plain puts; after the first failure nothing more is
 * written and every later put is INVAL. */
static int test_sticky_writer(void)
{
    uint8_t a[16], b[16];
    fl_bytes_writer_t w;
    fl_bytes_sticky_writer_t s;
    const uint8_t id[3] = { 7, 8, 9 };

    memset(a, 0xAA, sizeof a);
    memset(b, 0xAA, sizeof b);
    fl_bytes_writer_init(&w, a, sizeof a);
    fl_bytes_sticky_init(&s, b, sizeof b);
    ASSERT(fl_codec_put_bytes(&w, id, 3) == FL_RESULT_OK);
    ASSERT(fl_codec_put_u32(&w, 0x01020304u) == FL_RESULT_OK);
    ASSERT(fl_codec_put_str8(&w, "hi") == FL_RESULT_OK);
    ASSERT(fl_bytes_sticky_put_bytes(&s, id, 3) == FL_RESULT_OK);
    ASSERT(fl_bytes_sticky_put_u32(&s, 0x01020304u) == FL_RESULT_OK);
    ASSERT(fl_bytes_sticky_put_str8(&s, "hi") == FL_RESULT_OK);
    ASSERT(!s.bad && s.w.len == w.len && memcmp(a, b, sizeof a) == 0);

    /* 10 bytes used, 6 left: a u64 does not fit, then even a 1-byte put is refused. */
    ASSERT(fl_bytes_sticky_put_u64(&s, 1u) == FL_RESULT_NOMEM && s.bad && s.w.len == 10u);
    ASSERT(fl_bytes_sticky_put_bytes(&s, id, 1) == FL_RESULT_INVAL && s.w.len == 10u);
    ASSERT(fl_bytes_sticky_put_u32(&s, 1u) == FL_RESULT_INVAL && s.w.len == 10u);
    ASSERT(fl_bytes_sticky_put_str8(&s, "") == FL_RESULT_INVAL && s.w.len == 10u);
    ASSERT(b[10] == 0xAAu);
    return 0;
}

int main(void)
{
    if (test_file_delivery_sequence() || test_overflow_and_short_read() || test_kq_sequence() ||
        test_str8_rules() || test_reader_sticky() ||
        test_put_bytes_guards_and_u16_reader() || test_null_dest_and_null_output() ||
        test_sticky_writer())
        return 1;
    printf("test_net_codec: ok\n");
    return 0;
}
